AssistantMessageToolRequest(name='create', tool_call_id='function-call-7ccf0250-392c-4e76-bd11-558718be5f43', arguments={'file_text': 'const { useState } = React;

const CheckboxGroup = ({ id, question, helpText, options, values, onChange }) => {
    return (
        <div className="form-field">
            <fieldset aria-describedby={helpText ? `${id}-help` : undefined}>
                <legend>{question}</legend>
                {helpText && (
                    <span id={`${id}-help`} className="help-text">
                        {helpText}
                    </span>
                )}
                <div className="options-group">
                    {options.map((option) => (
                        <label key={option} className="option-item">
                            <input
                                type="checkbox"
                                checked={values.includes(option)}
                                onChange={(e) => onChange(option, e.target.checked)}
                            />
                            {option}
                        </label>
                    ))}
                </div>
            </fieldset>
        </div>
    );
};

const Quiz = () => {
    const [answers, setAnswers] = useState({
        q1: [],
        q2: [],
        q3: []
    });
    const [submitted, setSubmitted] = useState(false);

    const questions = [
        {
            id: 'q1',
            question: 'Which of the following are statically typed languages?',
            helpText: 'Statically typed languages check variable types at compile-time rather than at runtime.',
            options: ['Java', 'TypeScript', 'Python', 'JavaScript']
        },
        {
            id: 'q2',
            question: 'Which languages/technologies are primarily used for front-end web development?',
            options: ['HTML', 'CSS', 'JavaScript', 'SQL']
        },
        {
            id: 'q3',
            question: 'Which of the following are considered low-level or system programming languages?',
            options: ['C', 'Rust', 'Ruby', 'PHP']
        }
    ];

    const handleCheckboxChange = (questionId, option, checked) => {
        setAnswers(prev => {
            const current = prev[questionId];
            if (checked) {
                return { ...prev, [questionId]: [...current, option] };
            } else {
                return { ...prev, [questionId]: current.filter(item => item !== option) };
            }
        });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        setSubmitted(true);
    };

    return (
        <div className="quiz-container">
            <h1>Language Quiz</h1>
            <form onSubmit={handleSubmit}>
                {questions.map((q) => (
                    <CheckboxGroup
                        key={q.id}
                        id={q.id}
                        question={q.question}
                        helpText={q.helpText}
                        options={q.options}
                        values={answers[q.id]}
                        onChange={(option, checked) => handleCheckboxChange(q.id, option, checked)}
                    />
                ))}
                <button type="submit" className="submit-button">
                    Submit Answers
                </button>
            </form>

            {submitted && (
                <div className="results" role="alert">
                    <h2>Quiz Submitted!</h2>
                    <p>Thank you for participating. You selected {Object.values(answers).flat().length} total answers.</p>
                </div>
            )}
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<Quiz />);
