        {
            id: 'q2',
            question: 'Which languages/technologies are primarily used for front-end web development? (Select all that apply)',
            options: ['HTML', 'CSS', 'JavaScript', 'SQL']
        },
        {
            id: 'q3',
            question: 'Which of the following are considered low-level or system programming languages? (Select all that apply)',
            options: ['C', 'Rust', 'Ruby', 'PHP']
        }
    ];

