        setAnswers(prev => {
            const current = prev[questionId];
            if (checked) {
                return { ...prev, [questionId]: [...current, option] };
            } else {
                return { ...prev, [questionId]: current.filter(item => item !== option) };
            }
        });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        setSubmitted(true);
    };

    return (
        <div className="quiz-container">
            <h1>Language Quiz</h1>
            <form onSubmit={handleSubmit}>
                {questions.map((q) => (
                    <CheckboxGroup
                        key={q.id}
                        id={q.id}
                        question={q.question}
                        helpText={q.helpText}
                        options={q.options}
                        values={answers[q.id]}
                        onChange={(option, checked) => handleCheckboxChange(q.id, option, checked)}
                    />
                ))}
                <button type="submit" className="submit-button">
                    Submit Answers
                </button>
            </form>

            {submitted && (
                <div className="results" role="alert" aria-live="polite">
                    <h2>Quiz Submitted!</h2>
                    <p>Thank you for participating. You selected {Object.values(answers).flat().length} total answers.</p>
                </div>
            )}
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<Quiz />);
